def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    rem = 100 - n
    if rem <= 0:
        return 'D'
    if rem == 1:
        return 'D'

    my_seq = [h[0] for h in history]
    opp_seq = [h[1] for h in history]

    opp_coops = 0
    my_coops = 0
    for i in range(n):
        if opp_seq[i] == 'C':
            opp_coops += 1
        if my_seq[i] == 'C':
            my_coops += 1

    opp_rate = opp_coops / n
    my_rate = my_coops / n
    opp_defs = n - opp_coops

    rl = 12 if n > 12 else n
    recent_opp = opp_seq[-rl:]
    rec_c = 0
    for x in recent_opp:
        if x == 'C':
            rec_c += 1
    rec_d = rl - rec_c
    recent_rate = rec_c / rl

    rs = n - rl
    if rs < 1:
        rs = 1
    rh = 0
    rt = 0
    for i in range(rs, n):
        if my_seq[i - 1] == opp_seq[i]:
            rh += 1
        rt += 1
    react_rate = rh / rt if rt > 0 else 1.0

    my_last = my_seq[-1]
    opp_last = opp_seq[-1]

    opp_val = opp_last
    opp_streak = 0
    for x in reversed(opp_seq):
        if x == opp_val:
            opp_streak += 1
        else:
            break

    my_D_streak = 0
    if my_last == 'D':
        for x in reversed(my_seq):
            if x == 'D':
                my_D_streak += 1
            else:
                break

    my_val = my_last
    my_streak = 0
    for x in reversed(my_seq):
        if x == my_val:
            my_streak += 1
        else:
            break

    periodic = False
    if opp_coops > 0 and opp_defs > 0 and rec_c >= 3 and rec_d >= 3 and rl >= 8 and react_rate < 0.6:
        best_p = 0
        best_acc = 0.0
        maxp = rl - 3
        if maxp > 7:
            maxp = 7
        for p in range(2, maxp + 1):
            tot = rl - p
            if tot < 3:
                continue
            hits = 0
            for i in range(p, rl):
                if recent_opp[i] == recent_opp[i - p]:
                    hits += 1
            acc = hits / tot
            if acc > best_acc:
                best_acc = acc
                best_p = p
        if best_p != 0 and best_acc >= 0.85:
            periodic = True

    if periodic:
        return 'D'

    if opp_last == 'C':
        if my_last == 'D':
            if my_D_streak >= 2 and (opp_rate > 0.45 or recent_rate > 0.3):
                return 'D'
            if n >= 3 and history[-2] == ('C', 'C') and history[-3] == ('D', 'C') and opp_rate > 0.4:
                return 'D'
            return 'C'

        if n >= 2 and history[-2] == ('D', 'C') and opp_rate > 0.45 and recent_rate > 0.35:
            return 'D'

        if opp_coops == n and my_coops == n and 50 <= n <= 60:
            return 'D'

        if (n < 25 and opp_defs >= 4 and opp_streak == 2 and my_streak == 2 and recent_rate > 0.4 and opp_rate > 0.5):
            return 'D'

        return 'C'

    if n >= 2 and my_last == 'C' and history[-2] == ('D', 'C'):
        return 'C'

    if opp_coops == 0:
        if n <= 2 and opp_streak == 1:
            return 'C'
        if opp_streak >= 4 and n < 6:
            return 'C'
        return 'D'

    if opp_streak == 1:
        if opp_rate > 0.5 and recent_rate > 0.3 and my_rate > 0.3:
            return 'C'
        return 'D'

    if opp_streak == 2:
        if opp_rate > 0.6 and recent_rate > 0.4 and my_rate > 0.4:
            return 'C'
        return 'D'

    if n < 25 and my_last == 'D' and opp_streak <= 8 and opp_rate > 0.35 and recent_rate > 0.15:
        return 'C'

    return 'D'
